// Ports rdkit/Chem/Fraggle/UnitTestFraggle.py and FraggleSim's doctests;
// values from Python's module in RDKit 2024.03.6, generated by running it
// on the same input.

use rdkit_cxx::chem::fraggle::fraggle_sim::*;
use rdkit_cxx::chem::{
    SmilesParserParams, get_mol_frags_as_mols_with_sanitize_frags, mol_from_smiles,
    mol_from_smiles_with_params, mol_to_smiles,
};
use rdkit_cxx::{Error, Result};

fn unsanitized(smiles: &str) -> rdkit_cxx::chem::Mol {
    mol_from_smiles_with_params(
        smiles,
        &SmilesParserParams {
            sanitize: false,
            ..Default::default()
        },
    )
    .unwrap()
}

#[test]
fn fragmentations() -> Result<()> {
    assert_eq!(
        generate_fraggle_fragmentation(&mol_from_smiles(
            "COc1cc(CN2CCC(CC2)NC(=O)c2cncc(C)c2)c(OC)c2ccccc12"
        )?)?,
        vec![
            "*C(=O)NC1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1",
            "*C1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1",
            "*C1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1.*C(=O)c1cncc(C)c1",
            "*C1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1.*c1cncc(C)c1",
            "*Cc1cc(OC)c2ccccc2c1OC.*C(=O)c1cncc(C)c1",
            "*Cc1cc(OC)c2ccccc2c1OC.*NC(=O)c1cncc(C)c1",
            "*Cc1cc(OC)c2ccccc2c1OC.*c1cncc(C)c1",
            "*NC1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1",
            "*NC1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1.*c1cncc(C)c1",
            "*c1c(CN2CCC(NC(=O)c3cncc(C)c3)CC2)cc(OC)c2ccccc12",
            "*c1c(OC)cc(CN2CCC(NC(=O)c3cncc(C)c3)CC2)c(OC)c1*",
            "*c1cc(CN2CCC(NC(=O)c3cncc(C)c3)CC2)c(OC)c2ccccc12",
            "*c1cc(OC)c2ccccc2c1OC.*C(=O)c1cncc(C)c1",
            "*c1cc(OC)c2ccccc2c1OC.*N1CCC(NC(=O)c2cncc(C)c2)CC1",
            "*c1cc(OC)c2ccccc2c1OC.*NC(=O)c1cncc(C)c1",
            "*c1cc(OC)c2ccccc2c1OC.*c1cncc(C)c1"
        ]
    );
    assert_eq!(
        generate_fraggle_fragmentation(&mol_from_smiles("c12c(CCC)cccc2cccc1")?)?,
        vec![
            "*Cc1cccc2ccccc12",
            "*c1cccc(CCC)c1*",
            "*c1cccc2ccccc12",
            "*c1ccccc1*",
            "*c1ccccc1*.*CCC"
        ]
    );
    assert_eq!(
        generate_fraggle_fragmentation(&mol_from_smiles(
            "COc1cc(CN2CCC(NC(=O)c3ccccc3)CC2)c(OC)c2ccccc12"
        )?)?,
        vec![
            "*C1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1.*C(=O)c1ccccc1",
            "*C1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1.*c1ccccc1",
            "*Cc1cc(OC)c2ccccc2c1OC.*C(=O)c1ccccc1",
            "*Cc1cc(OC)c2ccccc2c1OC.*NC(=O)c1ccccc1",
            "*Cc1cc(OC)c2ccccc2c1OC.*c1ccccc1",
            "*NC1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1.*c1ccccc1",
            "*c1c(CN2CCC(NC(=O)c3ccccc3)CC2)cc(OC)c2ccccc12",
            "*c1c(OC)cc(CN2CCC(NC(=O)c3ccccc3)CC2)c(OC)c1*",
            "*c1cc(CN2CCC(NC(=O)c3ccccc3)CC2)c(OC)c2ccccc12",
            "*c1cc(OC)c2ccccc2c1OC.*C(=O)c1ccccc1",
            "*c1cc(OC)c2ccccc2c1OC.*N1CCC(NC(=O)c2ccccc2)CC1",
            "*c1cc(OC)c2ccccc2c1OC.*NC(=O)c1ccccc1",
            "*c1cc(OC)c2ccccc2c1OC.*c1ccccc1"
        ]
    );
    assert_eq!(
        generate_fraggle_fragmentation(&mol_from_smiles("COc1ccccc1")?)?,
        vec!["*c1ccccc1"]
    );
    Ok(())
}

#[test]
fn selections() -> Result<()> {
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*C.*O*.*c1cccc2ccccc12"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "acyclic", 12)?.as_deref(),
        Some("*c1cccc2ccccc12"),
        "*C.*O*.*c1cccc2ccccc12"
    );
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*CC.*O*.*c1ccccc1"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "acyclic", 9)?.as_deref(),
        Some("*c1ccccc1"),
        "*CC.*O*.*c1ccccc1"
    );
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*CC.*OCC*.*c1ccccc1"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "acyclic", 11)?.as_deref(),
        Some("*c1ccccc1"),
        "*CC.*OCC*.*c1ccccc1"
    );
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*CC.*OCCC*.*c1ccccc1"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "acyclic", 12)?.as_deref(),
        None,
        "*CC.*OCCC*.*c1ccccc1"
    );
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*C.*O*.*c1ccccc1"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "acyclic", 8)?.as_deref(),
        Some("*c1ccccc1"),
        "*C.*O*.*c1ccccc1"
    );
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*CCC.*O*.*c1ccccc1"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "acyclic", 10)?.as_deref(),
        Some("*CCC.*c1ccccc1"),
        "*CCC.*O*.*c1ccccc1"
    );
    let mut frags = get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*CC.*CC.*CC"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "acyclic", 6)?.as_deref(),
        None,
        "*CC.*CC.*CC"
    );
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*CCC.*CCC.*CCC"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "acyclic", 6)?.as_deref(),
        Some("*CCC.*CCC.*CCC"),
        "*CCC.*CCC.*CCC"
    );
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*c1ccccc1*.*cccc*"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "cyclic", 10)?.as_deref(),
        Some("*c1ccccc1*"),
        "*c1ccccc1*.*cccc*"
    );
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*c1ccccc1*.*C.*C"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "cyclic", 8)?.as_deref(),
        None,
        "*c1ccccc1*.*C.*C"
    );
    let mut frags = get_mol_frags_as_mols_with_sanitize_frags(
        &unsanitized("*c1ccccc1*.*c(CCCCCCCCCC)ccc*"),
        false,
    )?;
    assert_eq!(
        select_fragments(&mut frags, "cyclic", 20)?.as_deref(),
        None,
        "*c1ccccc1*.*c(CCCCCCCCCC)ccc*"
    );
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*c1ccccc1*.*CCC.*C"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "cyclic_and_acyclic", 10)?.as_deref(),
        Some("*c1ccccc1*.*CCC"),
        "*c1ccccc1*.*CCC.*C"
    );
    let mut frags =
        get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("*CCC.*C.*c1ccccc1*"), false)?;
    assert_eq!(
        select_fragments(&mut frags, "cyclic_and_acyclic", 10)?.as_deref(),
        Some("*CCC.*c1ccccc1*"),
        "*CCC.*C.*c1ccccc1*"
    );
    let mut frags = get_mol_frags_as_mols_with_sanitize_frags(
        &unsanitized("*CCC.*CCCCCCCCCCC*.*c1ccccc1*"),
        false,
    )?;
    assert_eq!(
        select_fragments(&mut frags, "cyclic_and_acyclic", 25)?.as_deref(),
        None,
        "*CCC.*CCCCCCCCCCC*.*c1ccccc1*"
    );
    let mut frags = get_mol_frags_as_mols_with_sanitize_frags(&unsanitized("CCCC"), false)?;
    assert!(matches!(
        select_fragments(&mut frags, "InvalidFragmentationType", 10),
        Err(Error::Value { .. })
    ));
    Ok(())
}

#[test]
fn ring_cuts() -> Result<()> {
    assert!(!is_valid_ring_cut(&mut mol_from_smiles("*CCC*")?)?);
    assert!(is_valid_ring_cut(&mut mol_from_smiles("*C1CC1*")?)?);
    assert!(is_valid_ring_cut(&mut mol_from_smiles("*c1ccccc1*")?)?);
    assert!(!is_valid_ring_cut(&mut unsanitized("*cccc*"))?);
    let mol = mol_from_smiles("COc1cc(CN2CCC(NC(=O)c3cncc(C)c3)CC2)c(OC)c2ccccc12")?;
    assert_eq!(
        delete_bonds(&mol, &[(1, 2), (10, 11)], "acyclic", 31)?.as_deref(),
        None
    );
    assert_eq!(
        delete_bonds(&mol, &[(3, 2), (4, 5)], "acyclic", 31)?.as_deref(),
        None
    );
    Ok(())
}

#[test]
fn similarities() -> Result<()> {
    let (sim, best) = get_fraggle_similarity(
        &mol_from_smiles("COc1cc(CN2CCC(NC(=O)c3cncc(C)c3)CC2)c(OC)c2ccccc12")?,
        &mol_from_smiles("COc1cc(CN2CCC(NC(=O)c3ccccc3)CC2)c(OC)c2ccccc12")?,
    )?;
    assert!((sim - 0.98046875).abs() < 1e-12, "{sim}");
    assert_eq!(best.as_deref(), Some("*C1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1"));
    let (sim, best) = get_fraggle_similarity(
        &mol_from_smiles("COc1cc(CN2CCC(NC(=O)c3cncc(C)c3)CC2)c(OC)c2ccccc12")?,
        &mol_from_smiles("COc1cc(CN2CCC(Nc3nc4ccccc4s3)CC2)c(OC)c2ccccc12")?,
    )?;
    assert!((sim - 0.7948717948717948).abs() < 1e-12, "{sim}");
    assert_eq!(best.as_deref(), Some("*C1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1"));
    let (sim, best) = get_fraggle_similarity(
        &mol_from_smiles("COc1ccccc1")?,
        &mol_from_smiles("COc1cc(CN2CCC(Nc3nc4ccccc4s3)CC2)c(OC)c2ccccc12")?,
    )?;
    assert!((sim - 0.3474576271186441).abs() < 1e-12, "{sim}");
    assert_eq!(best.as_deref(), Some("*c1ccccc1"));
    let (sim, best) = get_fraggle_similarity(
        &mol_from_smiles("COc1ccccc1")?,
        &mol_from_smiles("COc1cc(CN2CCC(NC(=O)c3ccccc3)CC2)c(OC)c2ccccc12")?,
    )?;
    assert!((sim - 0.2662337662337662).abs() < 1e-12, "{sim}");
    assert_eq!(best.as_deref(), Some("*c1ccccc1"));
    let (sim, best) =
        get_fraggle_similarity(&mol_from_smiles("CCCC")?, &mol_from_smiles("CCCCO")?)?;
    assert!((sim - 0.0).abs() < 1e-12, "{sim}");
    assert_eq!(best.as_deref(), None);
    let (sim, best) = get_fraggle_similarity_with_tversky_thresh(
        &mol_from_smiles("COc1cc(CN2CCC(NC(=O)c3cncc(C)c3)CC2)c(OC)c2ccccc12")?,
        &mol_from_smiles("COc1cc(CN2CCC(NC(=O)c3ccccc3)CC2)c(OC)c2ccccc12")?,
        0.95,
    )?;
    // From a fresh Python process: Python's cache of modified queries is
    // keyed without the threshold, so after the calls above it would reuse
    // their 0.8 fingerprints.
    assert!((sim - 0.9871794871794872).abs() < 1e-12, "{sim}");
    assert_eq!(
        best.as_deref(),
        Some("*c1cc(OC)c2ccccc2c1OC.*C(=O)c1cncc(C)c1")
    );
    let m = mol_from_smiles("COc1cc(CN2CCC(NC(=O)c3ccccc3)CC2)c(OC)c2ccccc12")?;
    assert_eq!(
        mol_to_smiles(&atom_contrib("*C1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1", &m)?)?,
        "COc1cc(C[Sc]2[Sc][Sc][Sc]([Sc][Sc](=[Sc])*3:*:*:*:*:*:3)[Sc][Sc]2)c(OC)c2ccccc12"
    );
    let (a, b) = compute_fraggle_similarity_for_subs(
        &m,
        &mol_from_smiles("COc1cc(CN2CCC(NC(=O)c3cncc(C)c3)CC2)c(OC)c2ccccc12")?,
        "",
        "*C1CCN(Cc2cc(OC)c3ccccc3c2OC)CC1",
    )?;
    assert!((a - 0.8202247191011236).abs() < 1e-12 && (b - 0.98046875).abs() < 1e-12);
    Ok(())
}

#[test]
fn attributes() -> Result<()> {
    assert_eq!(rdkit_fp_params().max_path, 5);
    assert_eq!(
        (ftype_acyclic(), ftype_cyclic(), ftype_cyclic_acyclic()),
        ("acyclic", "cyclic", "cyclic_and_acyclic")
    );
    assert!(mol_from_smiles("CC")?.has_substruct_match(&acyc_smarts())?);
    assert!(mol_from_smiles("C1CCC2CCCCC2C1C")?.has_substruct_match(&cyc_smarts())?);
    assert!(mol_from_smiles("*C1CCC1*")?.has_substruct_match(&c_sma1())?);
    assert!(mol_from_smiles("*C1(*)CCC1")?.has_substruct_match(&c_sma2())?);
    assert_eq!(
        mol_from_smiles("*CC*")?
            .get_atoms_matching_query(&dummy_atom_query())?
            .len(),
        2
    );
    Ok(())
}
